import { motion } from "framer-motion";
import React from "react";
import { FiExternalLink, FiCode, FiAward, FiTarget, FiZap, FiCpu } from "react-icons/fi";
import { problemSolvingData } from "./problemSolvingData";

const ProblemSolving = () => {

  // Icon mapping function
  const getIcon = (iconName) => {
    const iconMap = {
      FiCode: FiCode,
      FiTarget: FiTarget,
      FiZap: FiZap,
      FiCpu: FiCpu,
    };
    
    const IconComponent = iconMap[iconName];
    return IconComponent ? <IconComponent className="text-2xl" /> : <div className="text-2xl">🏆</div>;
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        duration: 0.6,
        staggerChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { y: 30, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        duration: 0.5,
        ease: "easeOut"
      }
    }
  };

  return (
    <section className="py-12 bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 relative overflow-hidden">
      {/* Background Effects */}
      <div className="absolute inset-0">
        <div className="absolute top-0 left-0 w-72 h-72 bg-cyan-500/10 rounded-full blur-3xl animate-pulse" />
        <div className="absolute bottom-0 right-0 w-96 h-96 bg-blue-500/10 rounded-full blur-3xl animate-pulse delay-1000" />
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-80 h-80 bg-purple-500/5 rounded-full blur-3xl animate-pulse delay-500" />
      </div>

      <div className="container mx-auto px-4 relative z-10">
        {/* Header Section */}
        <motion.div
          initial={{ opacity: 0, y: 50 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="text-center mb-8"
        >
          <motion.div
            initial={{ scale: 0 }}
            whileInView={{ scale: 1 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="inline-flex items-center gap-4 px-8 py-4 rounded-full bg-gradient-to-r from-cyan-500/20 to-blue-500/20 border border-cyan-500/30 mb-6"
          >
            <FiCode className="text-cyan-400 text-5xl md:text-6xl lg:text-7xl" />
            <span className="text-cyan-400 font-bold text-5xl md:text-6xl lg:text-7xl">Problem Solving</span>
          </motion.div>
          
          <h2 className="text-5xl md:text-6xl lg:text-7xl font-bold bg-gradient-to-r from-white via-cyan-100 to-blue-200 bg-clip-text text-transparent mb-4">
            {problemSolvingData?.title || ""}
          </h2>
          <p className="text-xl text-gray-400 max-w-3xl mx-auto leading-relaxed">
            {problemSolvingData?.description || "Passionate about algorithmic problem solving and competitive programming"}
          </p>
        </motion.div>

        {/* Content Section - Platforms Only */}
        <motion.div
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          className="min-h-[400px]"
        >
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6"
          >
            {problemSolvingData?.platforms?.length > 0 ? (
              problemSolvingData.platforms.map((platform, index) => (
                <motion.div
                  key={platform.id || index}
                  variants={itemVariants}
                  whileHover={{ y: -5, scale: 1.02 }}
                  className="group relative"
                >
                  <div className={`p-6 rounded-xl bg-gradient-to-br ${platform.color || 'from-gray-700 to-gray-800'} bg-opacity-10 border border-white/10 backdrop-blur-sm hover:border-white/20 transition-all duration-500 relative overflow-hidden`}>
                    {/* Background Glow */}
                    <div className={`absolute -inset-0.5 bg-gradient-to-r ${platform.color || 'from-gray-500 to-gray-600'} rounded-xl blur opacity-0 group-hover:opacity-20 transition duration-500`} />
                    
                    {/* Content */}
                    <div className="relative z-10">
                      {/* Header */}
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-3">
                          <div className="text-2xl">{getIcon(platform.icon)}</div>
                          <div>
                            <h3 className="text-lg font-bold text-white">{platform.name || "Platform"}</h3>
                            <p className="text-sm text-gray-400">@{platform.username || "username"}</p>
                          </div>
                        </div>
                        <motion.a
                          href={platform.profileUrl || "#"}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="p-2 rounded-lg bg-white/5 hover:bg-white/10 transition-colors"
                          whileHover={{ scale: 1.1, rotate: 15 }}
                          whileTap={{ scale: 0.9 }}
                        >
                          <FiExternalLink className="text-gray-400" />
                        </motion.a>
                      </div>

                      {/* Stats */}
                      <div className="grid grid-cols-2 gap-3 mb-4">
                        {platform.stats ? Object.entries(platform.stats).slice(0, 4).map(([key, value]) => (
                          <div key={key} className="text-center">
                            <div className="text-base font-bold text-white">{value}</div>
                            <div className="text-xs text-gray-400 capitalize">{key.replace(/([A-Z])/g, ' $1').trim()}</div>
                          </div>
                        )) : (
                          <div className="col-span-2 text-center text-gray-400 text-xs">No stats available</div>
                        )}
                      </div>

                      {/* Achievements */}
                      <div className="space-y-1">
                        <div className="flex items-center gap-1 text-xs text-gray-300 mb-1">
                          <FiAward className="text-yellow-400 text-sm" />
                          <span className="font-medium">Achievements</span>
                        </div>
                        {platform.achievements?.length > 0 ? platform.achievements.slice(0, 2).map((achievement, idx) => (
                          <div key={idx} className="text-xs text-gray-400 flex items-center gap-1">
                            <div className="w-1 h-1 rounded-full bg-cyan-400"></div>
                            {achievement}
                          </div>
                        )) : (
                          <div className="text-xs text-gray-400">No achievements listed</div>
                        )}
                      </div>
                    </div>
                  </div>
                </motion.div>
              ))
            ) : (
              <div className="col-span-full text-center text-gray-400">
                <p className="text-xl mb-4">No platforms data available</p>
                <p className="text-sm">Please check the problemSolvingData.js file</p>
              </div>
            )}
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
};

export default ProblemSolving;
